# runtime (agentseam dispatch, specialized to cursor)

_VOUCH_SPEAKS = False
_WARN_SPEAKS = False
_TRANSFORM_EVENTS = frozenset(('pre_tool',))


def degrade(decision, event):
    """Reduce a decision to what 'cursor' can actually honor, honestly.

    This is agentseam.dispatch.degrade(), specialized to one fixed agent so this file needs
    no "import agentseam" -- no evidence establishes that an explicit approval word means anything beyond a plain allow here, so vouch degrades to one; see agentseam.allow_semantics.
    """
    if decision.outcome == TRANSFORM and event.event not in _TRANSFORM_EVENTS:
        evidence = dict(decision.evidence)
        evidence["degraded_from"] = TRANSFORM
        return Decision.escalate(
            decision.reason or "input requires modification before it can run", evidence=evidence
        )
    if decision.outcome == VOUCH and not _VOUCH_SPEAKS:
        evidence = dict(decision.evidence)
        evidence["degraded_from"] = VOUCH
        return Decision.allow(decision.reason, evidence=evidence, context=decision.context)
    if decision.outcome == WARN and not _WARN_SPEAKS:
        evidence = dict(decision.evidence)
        evidence["degraded_from"] = WARN
        return Decision.allow(decision.reason, evidence=evidence, context=decision.context)
    return decision


# >>> agentseam handler >>>
# Not self-contained: chock's guard logic lives in the sibling _chock_runtime.py, loaded from this
# file's own folder and pinned to the sha256 of that file's bytes (CRLF read as LF), hashed before they are executed.
# Missing, unreadable, another version, or failing to import: every call refuses (_CHOCK_RUNTIME_FAULT), never allows.
_CHOCK_RUNTIME_PIN = '7ad185c06c529b9d8174cc9faeece81f92a75732282baa0bccee772d06d92787'


def _chock_load_runtime():
    """Bind the pinned shared runtime's names here; the reason it could not be, or None."""
    here = _chock_os.path.dirname(_chock_os.path.realpath(globals().get("__file__") or sys.argv[0]))
    if sys.path[:1] != [here]:
        sys.path.insert(0, here)
    path = _chock_os.path.join(here, '_chock_runtime.py')
    try:
        from hashlib import sha256
        from importlib.abc import InspectLoader
        from importlib.util import module_from_spec, spec_from_loader

        class PinnedBytes(InspectLoader):
            """Hands the import machinery the bytes already read and hashed; it never opens the file again."""

            def __init__(self, source):
                self.source = source

            def get_source(self, fullname):
                return self.source.decode("utf-8")

            def get_code(self, fullname):
                return compile(self.source, path, "exec")

        with open(path, "rb") as handle:
            source = handle.read()
        if sha256(source.replace(b"\r\n", b"\n")).hexdigest() != _CHOCK_RUNTIME_PIN:
            return "%s is not the version this entry was built with" % path
        loader = PinnedBytes(source)
        shared = module_from_spec(spec_from_loader('_chock_runtime', loader))
        shared.__file__ = path
        shared.__loader__ = loader
        loader.exec_module(shared)
    except BaseException as exc:  # noqa: BLE001 -- a SystemExit from its top level must refuse too
        return "chock could not load %s (%s)" % (path, type(exc).__name__)
    globals().update((name, value) for name, value in vars(shared).items() if not name.startswith("__"))
    return None


_CHOCK_RUNTIME_FAULT = _chock_load_runtime()
if _CHOCK_RUNTIME_FAULT is not None:
    _CHOCK_RUNTIME_FAULT += (
        "; refusing every call rather than allowing what it cannot check. Run `chock sync` (or reinstall the plugin)."
    )

_CHOCK_UNREADABLE = (
    "chock could not read this hook's payload, so it could not check the call. "
    "Refusing rather than reporting an allow it never established."
)

#: A payload naming only this vendor's own wire event, so `respond` picks that event's grammar.
_CHOCK_WIRE_RAW = {PRE_TOOL: {'hook_event_name': 'preToolUse'}, STOP: {'hook_event_name': 'stop'}}

#: The words a client reads as a refusal, in any of the answer fields a vendor grammar uses.
_CHOCK_REFUSING = ("deny", "block", "ask", "continue")
_CHOCK_ANSWER_KEYS = ("decision", "permission", "permissionDecision")


def _chock_spec_action(path):
    try:
        action = json.loads(path.read_text(encoding="utf-8")).get("action")
    except Exception:
        return "block"
    return action if action in ("ask", "warn") else "block"


def _chock_declared():
    """(strictest action, event, gate) of the judging flags; (None, None, None) where this run judges nothing."""
    argv = sys.argv[1:]
    actions = ["block"] if guard_path_from_argv(argv) is not None else []
    event = PRE_TOOL
    gate = _flag_path(argv, GATE_FLAG)
    if gate is not None:
        actions.append(_chock_spec_action(gate))
        event = STOP if STOP_FLAG in argv or gate.parent.name == _EVENT_ARG[STOP] else PRE_TOOL
    called = _flag_path(argv, TOOL_CALL_FLAG)
    if called is not None:
        actions.append(_chock_spec_action(called))
    if HALT_HOOK_FLAG in argv and repo_stop_refusal(Event(AGENT, PRE_TOOL, raw={})) is not None:
        actions.append("block")  # stopped: a payload nobody can read is still a call the stop refuses
    for action in ("block", "ask", "warn"):
        if action in actions:
            return action, event, gate
    return None, None, None


def _chock_refuses(text, code):
    if code == 2:
        return True
    try:
        body = json.loads(text)
    except Exception:
        return False
    if not isinstance(body, dict):
        return False
    nested = body.get("hookSpecificOutput")
    answers = [body] + ([nested] if isinstance(nested, dict) else [])
    return any(part.get(key) in _CHOCK_REFUSING for part in answers for key in _CHOCK_ANSWER_KEYS)


def _chock_unreadable_stop(gate):
    """The bounded verdict of an unreadable Stop: a refusal, or a warning once the cap is spent."""
    root = root_for(gate) or _chock_Path.cwd()
    return settle_unreadable_stop(root, gate.parent.parent.name, _CHOCK_UNREADABLE)


def _chock_runtime_refusal():
    """A refusal in this client's grammar for the event the flags name, read without the shared runtime."""
    _report(_CHOCK_RUNTIME_FAULT + "\n")
    argv = sys.argv[1:]
    gate = argv[argv.index('--gate') + 1] if '--gate' in argv[:-1] else ""
    stop = '--stop' in argv or _chock_os.path.basename(_chock_os.path.dirname(gate)) == 'stop'
    event = Event(AGENT, STOP if stop else PRE_TOOL, raw=dict(_CHOCK_WIRE_RAW[STOP if stop else PRE_TOOL]))
    text, code = respond(degrade(Decision.deny(_CHOCK_RUNTIME_FAULT), event), event)
    return (text, code) if _chock_refuses(text, code) else ("", 2)


def _chock_unreadable():
    if _CHOCK_RUNTIME_FAULT is not None:
        return _chock_runtime_refusal()
    action, kind, gate = _chock_declared()
    if action in (None, "warn"):
        return "", 0
    event = Event(AGENT, kind, raw=dict(_CHOCK_WIRE_RAW[kind]))
    reason = _CHOCK_UNREADABLE
    if kind == STOP and gate is not None:
        verdict, reason = _chock_unreadable_stop(gate)
        if verdict == VERDICT_WARN:
            return respond(degrade(Decision.warn(reason), event), event)
    _report(reason + "\n")
    decision = Decision.escalate(reason) if action == "ask" else Decision.deny(reason)
    judged = ["unreadable", None, _chock_time.monotonic(), {}]
    log_decision(sys.argv[1:], event, decision, judged, {"manifests": _CHOCK_PLUGIN_MANIFESTS})
    text, code = respond(degrade(decision, event), event)
    return (text, code) if _chock_refuses(text, code) else ("", 2)
#: Per wire event mapped to pre_tool: whether the client shows a guard's ask as a prompt.
_CHOCK_CAN_ASK = {'beforeMCPExecution': True, 'beforeReadFile': False, 'beforeShellExecution': True, 'beforeTabFileRead': False, 'preToolUse': False}
_CHOCK_EVENT_KEYS = ('hook_event_name', 'hookEventName', 'agent_action_name')
#: Where a plugin package's manifest may sit, relative to its root: the decision log reads its version.
_CHOCK_PLUGIN_MANIFESTS = ('.claude-plugin/plugin.json', '.codex-plugin/plugin.json', '.cursor-plugin/plugin.json', '.devin-plugin/plugin.json', 'gemini-extension.json', 'plugin.json', '.factory-plugin/plugin.json', 'kimi.plugin.json', '.plugin/plugin.json')


def _chock_wire_name(raw):
    names = (raw.get(key) for key in _CHOCK_EVENT_KEYS) if isinstance(raw, dict) else ()
    return next((name for name in names if isinstance(name, str)), None)


def _chock_wire(raw):
    return cursor_wire(raw)


def _chock_can_ask(raw):
    # An event this bundle cannot name, or one the vendor data does not list, cannot prompt.
    return _CHOCK_CAN_ASK.get(_chock_wire(raw), False)


def _spoken(verdict):
    outcome, reason = verdict
    if outcome == VERDICT_WARN:
        return Decision.warn(reason)
    return Decision.escalate(reason) if outcome == ESCALATE else Decision.deny(reason)


def _chock_timed(judged, stage, ask):
    started = _chock_time.monotonic()
    try:
        return ask()
    finally:
        judged[3][stage] = round((_chock_time.monotonic() - started) * 1000)


def _judge(event, judged):
    halted = repo_stop_refusal(event)
    if halted is not None:
        judged[0:2] = [HALT_REASON, ".chock/stop.json"]
        return Decision.deny(halted)
    if event.event == "pre_tool" and event.command:
        verdict = _chock_timed(judged, "guard", lambda: evaluate(
            sys.argv[1:], event.command, event.tool or "", can_ask=_chock_can_ask(event.raw)
        ))
        if verdict is not None:
            judged[0:2] = ["guard", _chock_Path(guard_path_from_argv(sys.argv[1:])).stem]
            outcome, reason = verdict
            return Decision.escalate(reason) if outcome == ESCALATE else Decision.deny(reason)
    gated = _chock_timed(judged, "gate", lambda: evaluate_gate(sys.argv[1:], event))
    if gated is not None:
        judged[0:2] = ["gate", gate_path_from_argv(sys.argv[1:]).parent.parent.name]
        return _spoken(gated)
    called = _chock_timed(judged, "tool_call", lambda: evaluate_tool_call(sys.argv[1:], event))
    if called is not None:
        judged[0:2] = ["tool_call", str(event.tool or "")]
        return _spoken(called)
    return None


def handle(event):
    if _CHOCK_RUNTIME_FAULT is not None:
        _report(_CHOCK_RUNTIME_FAULT + "\n")
        return Decision.deny(_CHOCK_RUNTIME_FAULT)
    starting = event.event == "session_start"
    if starting:
        log_heartbeat(event, _CHOCK_PLUGIN_MANIFESTS)
    # A door that cannot decide refuses. An exception escaping here would exit the hook
    # with a traceback, which every client reads as a non-blocking error: fail-open, with
    # the reason on a stderr nobody watches. The refusal carries the reason instead.
    judged = [None, None, _chock_time.monotonic(), {}]
    try:
        decision = _judge(event, judged)
    except Exception as exc:  # noqa: BLE001 -- any failure here must refuse, never fall through
        judged[0:2] = ["fault", type(exc).__name__]
        decision = Decision.deny(
            "chock could not check this call (%s: %s). Refusing rather than reporting an "
            "allow it never established." % (type(exc).__name__, exc)
        )
    context = {"manifests": _CHOCK_PLUGIN_MANIFESTS}
    try:
        context.update(wire=_chock_wire(event.raw), can_ask=_chock_can_ask(event.raw))
    except Exception:  # noqa: BLE001 -- the log's context must never change the decision
        pass
    if not starting:  # a session start's one line is its heartbeat
        log_decision(sys.argv[1:], event, decision, judged, context)
    return decision
# <<< agentseam handler <<<


def _coerce(result):
    if result is None:
        return Decision.allow()
    if isinstance(result, Decision):
        return result
    raise TypeError("handle() must return a Decision or None, got %r" % (type(result),))


def _read_payload(stream):
    # Decode bytes ourselves rather than trust the platform locale -- a BOM'd or non-UTF-8
    # stdin must not silently disable the gate. See agentseam.dispatch for the incident
    # this guards: a Windows console's cp1252 layer turning a UTF-8 BOM into three bytes
    # json cannot parse, with the hook allowing everything while claiming enforcement.
    buffer = getattr(stream, "buffer", None)
    if buffer is not None:
        return buffer.read().decode("utf-8-sig", errors="replace")
    return stream.read().lstrip("\ufeff")


def _emit(out, text):
    buffer = getattr(out, "buffer", None)
    if buffer is not None:
        buffer.write(text.encode("utf-8"))
        buffer.flush()
    else:
        out.write(text)
        out.flush()


def _report(text):
    # Best effort, never raising: a diagnostic must not pre-empt the refusal it accompanies.
    # A hook's stderr is whatever the host gave it -- closed (then sys.stderr is None, and
    # the traceback module's default print would land on STDOUT, inside the verdict), a
    # console code page that cannot hold the payload text quoted in the exception, a pipe
    # nobody reads.
    try:
        sys.stderr.write(text)
        sys.stderr.flush()
    except Exception:
        return


_STDERR_FD = 2


def _divert_fd1():
    """Point fd 1 at stderr (devnull if there is none); the saved fd 1, or None if it could not."""
    try:
        saved = os.dup(1)
    except OSError:
        return None
    # With fd 2 closed, dup() hands back 2 itself, and "stderr" would be stdout again.
    if saved > _STDERR_FD:
        with contextlib.suppress(OSError):
            os.dup2(_STDERR_FD, 1)
            return saved
    sink = os.open(os.devnull, os.O_WRONLY)
    os.dup2(sink, 1)
    os.close(sink)
    return saved


def _flush(streams):
    """Flush each stream that exists; a broken one is no reason to lose the verdict."""
    for stream in streams:
        if stream is not None:
            with contextlib.suppress(Exception):
                stream.flush()


@contextlib.contextmanager
def _stdout_to_stderr():
    # Stdout is the verdict channel. A handler's stray print (or a child process it runs)
    # ahead of the JSON makes the host fail to parse it, and Claude Code and Gemini CLI then
    # treat the hook as a non-blocking error: a deny became an allow, witnessed live.
    sink = sys.stderr if sys.stderr is not None else io.StringIO()
    held = (sys.stdout, sys.__stdout__)
    _flush(held)
    saved = _divert_fd1()
    try:
        with contextlib.redirect_stdout(sink):
            yield
    finally:
        if saved is not None:
            # A stream the handler held on to (sys.__stdout__, a reference cached at import)
            # buffers past redirect_stdout; flushed now it lands on stderr, not after the verdict.
            _flush((sink, *held))
            os.dup2(saved, 1)
            os.close(saved)


def _decide(raw):
    """(stdout_text, exit_code) for one decoded payload: agentseam.dispatch.handle(), inlined."""
    event = parse(raw)
    if event.event == UNKNOWN:
        # A vendor event this adapter has no mapping for. handle() is not called: it
        # reasons about the canonical vocabulary, and handing it something outside that
        # vocabulary invites a decision made on a false premise.
        return "", 0
    try:
        with _stdout_to_stderr():
            result = handle(event)
        decision = _coerce(result)
    except Exception:
        # A door that cannot decide refuses. Escaping here would exit 1 with a traceback,
        # which every host reads as a non-blocking error and allows past; instead the
        # failure is printed for the operator and the gate answers deny in 'cursor''s
        # own dialect. Only the failure's class is named to the host: its message may quote
        # the very payload content the policy was inspecting.
        _report(traceback.format_exc())
        decision = Decision.deny(
            "policy handler failed (%s); refusing rather than allowing what it could not judge"
            % sys.exc_info()[0].__name__
        )
    return respond(degrade(decision, event), event)


def main(stdin=None, stdout=None, exit=True):
    """Read one payload from stdin, dispatch, emit the 'cursor' response, exit."""
    stream = stdin if stdin is not None else sys.stdin
    out = stdout if stdout is not None else sys.stdout
    try:
        raw = json.loads(_read_payload(stream))
    except Exception:
        raw = None
    if not isinstance(raw, dict):
        text, code = _chock_unreadable()
        if text:
            _emit(out, text)
        if exit:
            sys.exit(code)
        return code
    try:
        text, code = _decide(raw)
    except Exception:
        # Past the handler, which _decide() already answers for: a fault in this file on a
        # payload it did decode. With no Event to answer in dialect, the one refusal left is
        # the host's blocking exit code, and nothing on stdout to be misread as a verdict.
        _report(traceback.format_exc())
        text, code = "", 2
    if text:
        _emit(out, text)
    if exit:
        sys.exit(code)
    return code


if __name__ == "__main__":  # pragma: no cover
    main()

